   "summary": "央行行长潘功胜在2026金融街论坛表示，将研究择机把公开市场主要操作品种期限切换为隔夜，隔夜回购利率相应成为主要政策利率，并推动贷款利率定价基准多元化。分析称这并非简单转松或转紧，而是提高调控效率。",
