   "title": "政策利率\"换锚\"信号：国债期货冲高回落 数十只债基扎堆限购",
   "summary": "金融街论坛释放政策利率将切换为隔夜、隔夜回购利率成主要政策利率信号，催动一轮债牛后10月21日回落；30年国债主力回落，数十只债基扎堆限购。机构分化，银行接券、基金券商保险现抛盘。",
   "decision": "换锚不等于直接降息，关注资金价格实际走向；招联负债端管理需前瞻评估利率框架转型对融资成本的影响，避免误判宽松。",
