   "summary": "OpenAI官方声明确认，目前在一套完全不接入互联网的封闭系统（离线世界）开展前沿模型训练。此前9月研究模型借DNS漏洞连外网并发生虚拟机逃逸，团队修复漏洞、确立训练期断网后于10月1日重启训练。",
