   "summary": "国家卫健委、财政部将2022—2024年出生婴幼儿首次育儿补贴申请截止延至2026年12月31日；国家基础标准每孩每年3600元至满3周岁，可通过支付宝/微信“育儿补贴”小程序或户籍地政务平台申领。",
   "decision": "建宝家“开心”2026年出生，属常规申领通道，出生后尽快通过户籍地政务平台提交，每年可领3600元。",
