   "summary": "WHO、联合国儿童基金会及多地妇幼保健院2026年更新建议：纯母乳或配方奶喂养约前6个月，之后在继续奶的基础上添加辅食，最佳窗口4-6个月，重点是坐立稳、挺舌反射消失等发育信号而非身份证月份。过早(4月前)增过敏噎呛风险，晚于7月增缺铁与咀嚼发育偏慢风险。",
