   "summary": "国家卫生健康委党组会议传达习近平总书记在纪念红军长征胜利90周年大会上的重要讲话，强调走好加快建设均衡普惠、优质高效健康中国的新的长征路，为“十五五”健康中国取得决定性进展提供政治保障。",
