   "summary": "截至9月底，贵州今年已发放育儿补贴40.84亿元，惠及131.31万个婴幼儿家庭；政策面向贵州户籍、3周岁以下婴幼儿，每孩每年3600元发至满3周岁，免征个税且不计入家庭收入。",
   "decision": "育儿补贴在全国加速落地，预产期临近的妻刘镜家庭可对照户籍地政策申领，减轻养育开支。",
