   "summary": "10月23日国常会指出要加快建设生育友好型社会，完善婚嫁生育养育教育政策，优化面向家庭的财税、社保、住房支持。分析认为母婴、育儿、早教等消费板块有望受益，多孩家庭公积金贷款额度普遍上浮。",
   "decision": "生育支持政策加码，妻育儿阶段可关注地方购房补贴、公积金上浮与托育消费券等实招。",
