   "summary": "重庆九龙坡等地落地生育保障新政：职工医保产前检查补助提至3000元、取消起付；10月1日起符合条件的住院分娩医保范围内费用全额支付；生育津贴由\"单位中转\"变\"个人直享\"，平均办理9个工作日；同步新生儿\"出生即参保\"。",
