   "summary": "国家医保局数据，2026年1-9月基本医保统筹基金总收入23028.33亿元、总支出17515.19亿元；其中职工医保统筹基金支出10044.28亿元，生育保险基金待遇支出1010.10亿元；城乡居民医保统筹基金支出7470.91亿元。",
