   "title": "世卫组织：刚果(金)埃博拉疫情出现反弹 母婴家庭关注出行卫生",
   "summary": "健康早闻提示，世卫组织通报刚果(金)埃博拉疫情出现反弹；同日《关于推动科技创新和产业创新深度融合的意见》发布，提出在量子科技、生物制造、脑机接口、具身智能等前沿领域加快产业化。",
   "decision": "若有出境计划需关注疫情与疫苗提醒；前沿生物制造政策利好长期健康产业发展，与家庭健康消费相关。",
