   "title": "中共中央国务院印发《关于发展新质生产力的意见》",
   "summary": "围绕科技创新、产业创新深度融合等5方面提出19项重点举措，统筹处理好政府和市场、自主和开放关系，以全要素生产率大幅提升为核心标志，加快发展新质生产力。",
   "decision": "新质生产力政策主线贯穿“十五五”，招联×联通数智化合作可对齐“科技创新+产业创新”叙事争取资源。",
