   "title": "党的二十届五中全会10月26日至29日在京举行，研究持之以恒推进全面从严治党",
   "summary": "中国共产党第二十届中央委员会第五次全体会议10月26日至29日在北京召开，习近平代表中央政治局作工作报告并就《中共中央关于持之以恒推进全面从严治党若干重大问题的决定（讨论稿）》作说明，全会吸引全球目光。",
   "decision": "全会聚焦全面从严治党，政策连续性与治理基调明确，利于中长期营商环境与金融合规预期稳定。",
   "source": "新华社/央视",
