   "summary": "中央纪委国家监委通报，1至9月全国纪检监察机关立案80万件，其中立案省部级及以上干部73人、厅局级干部4203人，反腐力度持续保持高压。",
   "decision": "反腐常态化强化合规与廉洁预期，金融行业展业需持续守住合规底线。",
