   "summary": "国家统计局发布数据，1至9月全国规模以上工业企业利润同比增长15.5%，今年以来持续保持两位数增长，经济回升基础进一步巩固。",
   "decision": "工业盈利改善反映内需与价格修复，对消费金融资产质量与广告主预算均偏正面。",
