   "summary": "中央网络安全和信息化委员会印发《国家信息化“十五五”规划》，系统擘画数字中国、数字经济与数字政府建设，为AI、算力、数据要素等提供顶层制度框架。",
   "decision": "信息化顶层规划落地，为招联数字化转型与数据合规应用提供政策确定性。",
