   "title": "国务院印发《知识产权保护和运用“十五五”规划》，高价值发明专利目标大于22件",
   "summary": "国务院印发《知识产权保护和运用“十五五”规划》，将每万人口高价值发明专利拥有量设定为大于22件，较“十四五”末16件增长6件以上，引导创新资源向重点领域集聚。",
   "decision": "知识产权全链条保护强化，利好硬科技与AI企业，招联相关技术专利布局可借势提速。",
   "source": "人民日报",
