   "title": "河南新增10类智能化产品以旧换新补贴 每件最高1500元",
   "summary": "河南省商务厅等联合优化2026年消费品以旧换新地方自主品类，在原有基础上新增10类智能化产品，每件最高补贴1500元。",
   "decision": "地方以旧换新扩围至智能产品，消费金融可嵌入家电/3C分期场景。",
