   "title": "广电总局新规：有线电视开机不得播广告 11月27日起施行",
   "summary": "国家广电总局《有线广播电视运营服务管理规定》要求取消开机广告、开机看全屏直播，设免费专区、简化遥控器一键切直播，投诉10个工作日内答复。",
   "decision": "与招联×联通“品牌泛曝光”投放渠道相关，电视端开机广告退出倒逼品牌曝光转向合规新场景。",
