   "summary": "中国共产党第二十届中央委员会第五次全体会议于10月26日至29日在北京召开，主要议程是中央政治局向中央委员会报告工作，研究持之以恒推进全面从严治党若干重大问题。",
   "decision": "五中全会定调宏观与治党方向，关系消费金融合规环境与国企展业基调。",
