   "summary": "国务院令与全会期间，数字人民币基础设施服务体系全面升级，叠加央行扩大SLF适用机构范围、推动银行间与交易所债市互联互通、试点境外金融机构境内外汇购售等举措，宏观审慎框架进一步完善。",
   "decision": "数字人民币生态完善，招联可关注其在合规放款、智能合约还款中的潜在应用。",
