   "title": "证监会就公募基金运作管理办法征求意见 放宽FOF与REITs",
   "summary": "证监会就《公开募集证券投资基金运作管理办法（征求意见稿）》及配套规则征求意见，降低FOF成立门槛、允许FOF投资ETF联接基金、将非FOF投资其他基金比例上限从10%提至30%，明确基金投资REITs按证券投资管理。",
   "decision": "公募资产配置结构性升级，关注居民财富向多元资产迁移对消费金融负债端的长期影响。",
