   "summary": "房地产政策端现房销售细则向三四线扩围（苏州、温州、十堰），住建部推动1500个老旧街区改造并发力REITs，政策“组合拳”持续破局。",
   "decision": "地产企稳有助居民资产负债表修复，对消费金融零售资产质量偏正面。",
