   "summary": "《保护中国商业秘密特别规定(征求意见稿)》公开征求意见，明确外国实体实施规定行为的，商务部可对其采取限制或禁止从事与中国有关的货物、技术进出口及国际服务贸易、禁止出口相关物项等措施。",
   "decision": "商业秘密保护强化，招联与联通等合作中的技术数据与合规信息须加强保密管理。",
