   "summary": "中办、国办《关于推动科技创新和产业创新深度融合的意见》对外发布，围绕促进创新链产业链无缝对接、以高质量科技供给支撑现代化产业体系、加强企业主导的产学研融通创新、提高创新资源统筹配置效能等6方面明确举措，提出在新业态新领域放宽市场准入试点、探索沙盒监管。",
   "decision": "科创与产业融合政策利好科技金融，招联可关注科创企业客群与场景金融机会。",
