   "title": "李强签署国务院令公布《事业单位登记管理条例》 12-1施行",
   "summary": "国务院总理李强签署国务院令公布《事业单位登记管理条例》，自2026年12月1日起施行，共6章34条。明确事业单位应坚持党的领导、强化公益性职责，不得偏离公益主责主业、不得违规举办企业、不得开展虚假宣传，并规范登记管理与简易注销。",
   "decision": "事业单位监管收紧，涉及招联等国企背景机构的合规参照与关联交易边界。",
   "source": "光明网/新华社",
   "url": "https://news.gmw.cn/2026-10/27/content_39067193.htm",
