   "title": "国常会：加快建设生育友好型社会 完善婚嫁生育养育教育政策",
   "summary": "国务院常务会议指出，人口是经济社会发展基础，要统筹人口与经济社会、资源环境关系，加快建设生育友好型社会，持续完善婚嫁、生育、养育、教育等政策，优化面向家庭的财税、社保、住房支持，稳定新出生人口规模。",
   "decision": "生育友好政策与妻育儿时点高度相关，可系统梳理补贴、公积金、个税等家庭可享红利。",
