   "title": "中办国办发布科技创新与产业创新深度融合意见",
   "summary": "10月21日中办、国办《关于推动科技创新和产业创新深度融合的意见》对外发布，提出建立企业出题、科研答题、市场阅卷的创新机制，从增强企业创新能力、培育科技企业、加强协同联动三方面安排，企业成创新主力军。",
   "decision": "两创融合意见利好科技型中小微企业，招联可将科创信贷与联通产业资源对接，形成专项产品。",
   "source": "中国经济时报",
