   "title": "前三季度服务业增加值同比增5.2% 对经济增长贡献率66.3%",
   "summary": "国家统计局数据，前三季度服务业增加值628255亿元同比增长5.2%，占GDP比重58.7%、比上年同期提高0.2个百分点，对经济增长贡献率66.3%、同比提高5.6个百分点，成第一大产业支撑。",
   "decision": "服务业主导结构深化，招联客群中的服务业从业者与小微商户信贷需求值得重点经营。",
