   "title": "二十届中央第七轮巡视反馈完成 15个巡视组向36家单位反馈",
   "summary": "三分钟新闻早餐报道，二十届中央第七轮巡视反馈工作完成，15个中央巡视组向36家中央和国家机关单位反馈问题，压实巡视整改责任，推动补齐制度短板。",
   "decision": "巡视整改强化合规与内控导向，金融机构须持续完善治理，招联应关注监管整改的同业传导。",
   "source": "三分钟新闻早餐",
