   "overseas": false,
   "title": "中共中央政治局10月23日审议二十届中央第七轮巡视综合报告",
   "summary": "中共中央政治局10月23日召开会议，审议《关于二十届中央第七轮巡视情况的综合报告》，习近平主持。会议指出巡视工作成效明显但存在问题需重视，要求压实整改责任、动真碰硬真改实改，持续深化全面从严治党。",
   "decision": "全面从严治党纵深推进，关注国企与金融机构巡视整改联动，对招联合规治理与内控建设形成外部牵引。",
   "source": "央视新闻联播",
