   "title": "商务部：全链条扩大汽车消费 出台智能产品消费应用方案",
   "summary": "商务部介绍\"十五五\"促消费举措：推动商品消费扩容升级、全链条扩大汽车消费；出台加快智能产品在消费领域应用工作方案；持续扩大服务消费，深化国际消费中心城市培育，加快补齐县域消费短板。",
   "decision": "汽车与智能产品消费政策直接关联消费金融分期场景，招联可借势拓展汽车、3C等场景化信贷产品。",
