   "summary": "上海市委财经委会议听取落实房地产发展新模式汇报，指出要把让人民宜居安居放在首位，加快建立高品质供给、高效率保障、高水平运行的房地产发展新模式，大力实施\"房屋品质提升工程\"，深化\"规储供用\"一体化机制。",
   "decision": "核心城市地产政策优化，关注其对居民财富与消费信心的影响，间接关联消金资产质量。",
