   "title": "全国退税商店超1.8万家 1-8月离境退税销售额同比增约6成",
   "summary": "商务部数据显示，全国退税商店已超过1.8万家，比2024年底增长4倍；今年1-8月全国离境退税销售额同比增长约6成，办理退税人数增长3倍；\"China Haul\"中国购物开箱热潮兴起。",
   "decision": "离境退税与入境消费升温，利好跨境支付与旅游消费金融，关注招联在入境消费场景的潜在合作空间。",
