   "summary": "沙特主导多国联军证实拦截胡塞武装射向塔伊夫的弹道导弹；胡塞方面称向沙特东部塔努拉角炼油厂发射导弹引发大火，沙特尚未证实。红海与霍尔木兹航运风险维持高位。",
