   "summary": "特朗普称“已击败伊朗、冲突很快结束”；美媒称美军拟打击清单含伊朗能源基础设施、军事场所与核设施，范围或扩大；以总理推动新一轮打击、美方要求推迟；美拟撤出中东多国使馆人员。",
