   "title": "霜降后两轮大降温来袭，25-27日西北至中东部降温4-6℃、局地达10℃",
   "summary": "受新一股冷空气影响，25日至27日西北地区到中东部多地有4至6℃降温，华北和东北部分地区降幅可达10℃左右；26日内蒙古东北部、黑龙江北部等地有小到中雪或雨夹雪，局地大雪。中央气象台提示防风保暖。",
   "decision": "寒潮来袭，建宝妻刘镜预产期临近、\"开心\"即将出生，务必注意母婴保暖与出行安全，减少受凉风险。",
