   "summary": "天津10月21日起施行公积金新政，住房物业费、装修费可提取住房公积金；天津市口腔医院梅江院区10月28日试开诊，华苑科技园\"117项目\"片区网约公交试运营，西青区宠物主题市集开集。",
   "decision": "公积金使用范围扩围，建宝可关注家庭住房与装修资金安排，合理运用公积金。",
