   "summary": "南都调查指出，人脸授权平台\"新爪AIGC\"授权用途分类含\"反派角色形象\"\"死亡戏\"\"情感亲密戏\"\"性感着装\"等敏感场景；平台创始人回应称设置分类是为让授权人更清晰表达意愿、双向选择，项目内容仍须遵守法规与审核。",
   "decision": "人脸等生物资产授权边界模糊，提醒家庭重视个人信息与肖像权保护；招联须严守生物识别数据合规与最小必要原则。",
