   "summary": "今年国庆，2014年出生的上海少年李毓民用时五天登顶海拔5895米的乞力马扎罗主峰；原定线路因山火改走更陡路线，母子均出现高反，母亲在距顶峰约200米处下撤，最后一段由父亲与向导陪完。母亲称这是一场成长试炼而非冲纪录。",
   "decision": "亲子共同挑战传递理性育儿观，新手父母可借鉴\"重过程轻标签\"的陪伴理念。",
