   "summary": "柬埔寨政府披露，法院已冻结涉及太子集团案件的近10亿美元资产，包括建筑物、赌场及数千处房地产；调查发现关联公司多达198家（98家在柬、100家海外），涉嫌有组织严重诈骗及洗钱，部分建筑与赌场被用于网络诈骗。",
